import EarlGrey from "./Users/eldarakhundzada/Desktop/CaySociety/teeShop/src/assets/teaBilder/EarlGrey.svg"

export default function buttons(){
    const teaName = [
        {name :'Earl Greay', Image: 'EarlGrey.svg'}
    ];

    return(
        <div>
            {teaName.map((tea, index) => (
                <button>
                    {tea.name}
                    <img src={tea.Image[index]} />
                </button>
            ))}
        </div>
    );
}
